func testProdutoTipoprodutoToOneDespesasUsingDesp(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local ProdutoTipoproduto
	var foreign Despesas

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, produtoTipoprodutoDBTypes, true, produtoTipoprodutoColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize ProdutoTipoproduto struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, despesasDBTypes, false, despesasColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Despesas struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	queries.Assign(&local.DespID, foreign.DespID)
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.Desp().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if !queries.Equal(check.DespID, foreign.DespID) {
		t.Errorf("want: %v, got %v", foreign.DespID, check.DespID)
	}

	ranAfterSelectHook := false
	AddDespesasHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *Despesas) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := ProdutoTipoprodutoSlice{&local}
	if err = local.L.LoadDesp(ctx, tx, false, (*[]*ProdutoTipoproduto)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Desp == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.Desp = nil
	if err = local.L.LoadDesp(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Desp == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

